void update(double dt, double friction, List<Rectangle> rectangles) {
  ball.position.x += velocityX * dt;
  ball.position.y += velocityY * dt;
  // Adicionando movimento em Z se necessário:
  ball.position.z += velocityZ * dt;

  velocityX *= friction;
  velocityY *= friction;

  // Calcula o eixo de rotação com base na direção do movimento
  Vector3 velocity = Vector3(velocityX, velocityY, velocityZ);

  // Determina o eixo de rotação como a direção da velocidade
  Vector3 rotationAxis = velocity.normalized(); // Usa a direção da velocidade como eixo

  if (rotationAxis.length > 0) {
    double speed = velocity.length();

    // Calculamos a quantidade de rotação
    double angle = speed * dt; 

    // Criar o quaternion de rotação
    Quaternion deltaRotation = Quaternion.axisAngle(rotationAxis, angle);

    // Atualiza a orientação: newOrientation = currentOrientation * deltaRotation
    orientation = orientation.multiply(deltaRotation); // Use multiply() para composição de quaternions
    orientation.normalize();

    // Aplicar a rotação à bola usando o quaternion
    ball.rotation.setFrom(orientation); // Use setFrom() se não houver applyQuaternion()
  }

